import os, re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        return {}
    session_file = f'{d}/../../sessions/{os.path.basename(d)}.jsonl'
    try:
        with open(session_file) as f:
            content = f.read()
    except:
        return {}

    G = {}
    inputs = []
    outputs = []
    test_input = None

    # Pattern matches demo/test input followed by grid data
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+?)(?=Demo pair|Test input|$)'

    for m in re.finditer(pattern, content, re.DOTALL):
        k = m.group(1)
        h, w = int(m.group(2)), int(m.group(3))
        grid_data = m.group(4).strip().split('\n')

        # Parse the grid rows
        rows = []
        for line in grid_data[:h]:
            cells = line.strip().split()
            rows.append([int(c) for c in cells])

        grid = rows

        if k == 'Test input':
            test_input = grid
        elif 'input' in k:
            inputs.append(grid)
        elif 'output' in k:
            outputs.append(grid)

    result = {'test_input': test_input, 'inputs': inputs, 'outputs': outputs}
    return result

G = load_grids()
print("Loaded:", list(G.keys()))
for key in ['test_input', 'inputs', 'outputs']:
    if key in G:
        print(f"\n{key}:")
        for i, item in enumerate(G[key]):
            import json
            print(json.dumps(item)[:200])

import os, re, json

d = os.environ.get('RLM_SESSION_DIR')
session_file = f'{d}/../../sessions/{os.path.basename(d)}.jsonl'

with open(session_file) as f:
    content = f.read()

# Simple approach: split on "Demo pair" or "Test input" markers
lines = content.split('\n')
current_grid = []
current_type = None
current_dims = None

all_grids = {}

for i, line in enumerate(lines):
    if 'Test input' in line:
        m = re.search(r'Test input \((\d+)x(\d+)\):\s*(.+)$', line, re.MULTILINE)
        if m:
            current_type = 'test_input'
            current_dims = (int(m.group(1)), int(m.group(2)))
            current_grid = []
            for j in range(i+1, len(lines)):
                next_line = lines[j]
                if 'Demo' in next_line or 'Test' in next_line:
                    break
                cells = next_line.strip().split()
                if cells:
                    current_grid.append([int(c) for c in cells])
            all_grids['Test input'] = current_grid
    elif 'Demo pair' in line and 'input' in line:
        m = re.search(r'Demo pair \d+ input \((\d+)x(\d+)\):\s*(.+)$', line, re.MULTILINE)
        if m:
            h, w = int(m.group(1)), int(m.group(2))
            grids_for_demo = [{} ]  # placeholder

            # Collect grid rows until we hit something that looks like another marker
            grid_rows = []
            for j in range(i+1, len(lines)):
                next_line = lines[j]
                if 'Demo' in next_line and 'input' in next_line:
                    break
                if 'output' in next_line.lower():
                    # End of this demo's input part
                    break
                cells = next_line.strip().split()
                if cells:
                    grid_rows.append([int(c) for c in cells])

            if len(grid_rows) == h:
                all_grids[f'Demo pair {h}x{w} input'] = grid_rows[:h]

    elif 'Demo pair' in line and 'output' in line:
        m = re.search(r'Demo pair \d+ output \((\d+)x(\d+)\):\s*(.+)$', line, re.MULTILINE)
        if m:
            h, w = int(m.group(1)), int(m.group(2))
            grid_rows = []
            for j in range(i+1, len(lines)):
                next_line = lines[j]
                if 'input' in next_line and 'Demo' in next_line:
                    break
                if next_line.strip() == '' or j > len(lines)-1:
                    break
                cells = next_line.strip().split()
                if cells:
                    grid_rows.append([int(c) for c in cells])

            if len(grid_rows) == h:
                all_grids[f'Demo pair {h}x{w} output'] = grid_rows[:h]

print("All grids loaded:", list(all_grids.keys()))
if all_grids:
    print("\nTest input:")
    print(json.dumps(all_grids.get('Test input')))

